import React, { useEffect, useState } from 'react';
import Head from './partials/head';
import Navbar from './partials/navbar';
import Footer from './partials/footer';
import config from '../config';
import axios from 'axios';



const CreateTable = () => {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.post(`${config.API_URL}/viewTable`)
      .then(response => {
        console.log(response.data);
        setGames(response.data.data); 
        setLoading(false);
      })
      .catch(error => {
        console.error("home.js 21: ", error.message);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div className="container-lg"><div className="alert alert-danger" role="alert">Shop Hiện Chưa Có Danh Mục Nào....</div></div>;
  }

  return (
    <div className="container-lg">

      {games.map(({ id, title, saleoff, updatedAt, data }) => (
        <div key={id}> {/* Ensure each game has a unique key */}
          <h2 className="guide__title">{title}</h2>
          <div className="row item-container">
            {data.map(({ id, content, bgimage, quantity }) => ( 
              <div key={id} className="col-md-3"> {/* Ensure each item inside data also has a unique key */}
                <div className="item-bounder">
                  
                  {saleoff > 0 && (
                    <div className="discount-badge">
                      <span className="discount-label">HOT sale off: {saleoff}%</span>
                    </div>
                  )}
                  
                  <div className="item-image mb-3">
                    <a href={`/account/category/${id}`}><img src={bgimage} alt="Game Category"/></a>
                  </div> 
                  <div className="item-caption"> 
                    <h3 className="text-center">{content}</h3>
                    <center><img width="90%" className="img-responsive" src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/hr_beautiful.webp" alt="Game Thumbnail" /></center>
                  </div>
                  <a href={`/account/category/${id}`} className="btn btn_left" role="button">Mua ngay</a>
                  <div className="account-remaining mt-3 text-center"><p><strong>Còn {quantity} tài khoản</strong></p></div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

const Home = () => {
  return (
    <>
      <Head />
      <div className="hold-transition sidebar-collapse layout-top-nav">
        <div className="wrapper">
          <Navbar />

          <section className="content">
            <div className="container-fluid">
             {/* eslint-disable-next-line jsx-a11y/alt-text */}
            <center><img src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/2020031919242255224.png" class="city__icon"/></center>

              <main>
                <div>
                  <div className="container-lg mb-3">
                    <div className="row mb-3">
                      <div className="col text-center">
                        <span className="mt-2">
                          {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}
                          <a href="#" className="dropdown-toggle" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">
                            <button className="btn-pretty">Hỗ Trợ</button>
                          </a>
                          <div className="dropdown-menu">
                            <div className="dropdown-divider"></div>
                          </div>
                        </span>

                        <span className="mt-2">
                          {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}
                          <a href="#" className="dropdown-toggle" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">
                            <button className="btn-pretty">Nạp Tiền</button>
                          </a>
                          <div className="dropdown-menu">
                            <a className="dropdown-item" href="/naptien"><i className="fas fa-university mr-1"></i> Chuyển Khoản</a>
                          </div>
                        </span>
                      </div>
                    </div>
                  </div>
                  <CreateTable />
                </div>
              </main>
              <Footer />
            </div>
          </section>
        </div>
      </div>
    </>
  );
};

export default Home;
