import React, { useEffect, useState } from 'react';
import config from '../../config';
import axios from 'axios';

const Navbar = () => {
  const [checkLogin, setCheckLogin] = useState(false);
  const [Credit, setCredit] = useState(0);
  const [Username, setUsername] = useState('');
  const [isOpen, setIsOpen] = useState(false); // For toggling the navbar on mobile view

  const infoUSER = async () => {
    try {
      const response = await axios.post(`${config.API_URL}/infoUSER`, {
        authorization: localStorage.getItem('authorization') || '0123',
      });
      if (response.data.type) {
        setCheckLogin(true);
        setCredit(response.data.data.credit);
        setUsername(response.data.data.username);
      }
    } catch (error) {
      console.log(error.message);
    }
  };

  useEffect(() => {
    const fetchInfo = async () => {
      await infoUSER();
      setTimeout(fetchInfo, 10000); // Update every 10 seconds
    };
    fetchInfo();
  }, []);

  const toggleNavbar = () => {
    setIsOpen(!isOpen); // Toggle the navbar state
  };

  return (
    <nav className="main-header navbar navbar-expand-md nav-header mb-4">
      <div className="container">
        {/* Navbar Toggler for Mobile */}
        <button
          className="navbar-toggler"
          type="button"
          onClick={toggleNavbar} // Toggle the navbar
          aria-controls="navbarNav"
          aria-expanded={isOpen ? 'true' : 'false'} // Toggle the value of aria-expanded based on isOpen
          aria-label="Toggle navigation"
        >
          <span className="navbar-toggler-icon">
            <i
              className="fas fa-bars"
              style={{ textShadow: '2px 2px 2px #000000', color: '#fff' }}
            ></i>
          </span>
        </button>

        {/* Navbar Menu Links */}
        <div
          className={`navbar-collapse order-3 collapse ${isOpen ? 'show' : ''}`} // Add 'show' class when navbar is open
          id="navbarNav"
        >
          <ul className="navbar-nav mx-auto">
            {/* Home */}
            <li className="nav-item">
              <a href="/" className="nav-link">
                Trang Chủ
              </a>
            </li>
            {/* Top Up */}
            <li className="nav-item dropdown">
              {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}
              <a
                href="#"
                className="nav-link dropdown-toggle"
                id="navbarDropdown"
                role="button"
                data-toggle="dropdown"
                aria-haspopup="true"
                aria-expanded="false"
              >
                Nạp tiền
              </a>
              <div className="dropdown-menu" aria-labelledby="navbarDropdown">
                <a
                  href="https://shoptethan.com/user/money/phone-card/send-card"
                  className="dropdown-item"
                >
                  Nạp bằng thẻ cào
                </a>
                <a
                  href="https://shoptethan.com/user/money/auto-bank/info"
                  className="dropdown-item"
                >
                  Nạp bằng bank, ví
                </a>
              </div>
            </li>
            {/* ROBLOX */}
            <li className="nav-item">
              <a href="https:///" className="nav-link">
                ROBLOX (all)
              </a>
            </li>
            {/* ZALO Admin */}
            <li className="nav-item">
              <a href="https://zalo.me/" className="nav-link">
                ZALO ADMIN
              </a>
            </li>

            {/* User Info (Username and Credit) */}
            {checkLogin && (
              <li className="nav-item dropdown">
                {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}

                <div className="dropdown-menu" aria-labelledby="navbarDropdown">
                  <a href="/profile" className="dropdown-item">
                    Profile
                  </a>
                  <a href="/settings" className="dropdown-item">
                    Settings
                  </a>
                  <div className="dropdown-divider"></div>
                  <a href="/logout" className="dropdown-item">
                    Log out
                  </a>
                </div>
              </li>
            )}
          </ul>
        </div>

        {/* User Info or Login Buttons */}
        <ul className="order-1 order-md-3 navbar-nav navbar-no-expand ml-auto">
          {checkLogin ? (
                // eslint-disable-next-line jsx-a11y/anchor-is-valid
                <a
                className="nav-link dropdown-toggle"
                type="button"
                onClick={toggleNavbar}
                aria-controls="navbarNav"
                aria-expanded={isOpen ? 'true' : 'false'} 
                aria-label="Toggle navigation"
              >
                <span className="text-success">{Username}:</span>{' '}
                {new Intl.NumberFormat('en-US').format(Credit)}
              </a>
          ) : (
            <>
              <li className="nav-item">
                <a href="/register">
                  <button className="btn-pretty">Đăng ký</button>
                </a>
              </li>
              <li className="nav-item">
                <a href="/login">
                  <button className="btn-pretty">Đăng nhập</button>
                </a>
              </li>
            </>
          )}
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
