import React from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import Home from './client/home';
import Acctype from './client/account-category';
import Login from './client/login';


const pageVariants = {
  initial: {
    opacity: 0,
    x: "100vw",
  },
  animate: {
    opacity: 1,
    x: 0,
    transition: {
      duration: 0.5,
      ease: "easeOut",
    },
  },
  exit: {
    opacity: 0,
    x: "-100vw",
    transition: {
      duration: 0.5,
      ease: "easeIn",
    },
  },
};

const AppRouter = () => {
  const location = useLocation(); 

  return (
    <AnimatePresence mode="wait"> 
      <motion.div
        key={location.pathname} // Mỗi route cần một key duy nhất
        variants={pageVariants}
        initial="initial"
        animate="animate"
        exit="exit"
      >
        <Routes location={location}>
          <Route path="/" element={<Home />} />
          <Route path="/account/category/:id" element={<Acctype />} />
          <Route path="/login" element={<Login />} />
        </Routes>
      </motion.div>
    </AnimatePresence>
  );
};

const App = () => (
  <Router>
    <AppRouter />
  </Router>
);

export default App;