import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import Head from './partials/head';
import Navbar from './partials/navbar';
import Footer from './partials/footer';
// import config from '../config';
// import axios from 'axios';

const FormSearch = () => {
    const [accId, setAccId] = useState(""); // Track the value of accId input
    const [price, setPrice] = useState(""); // Track the value of price input
    const [sortPrice, setSortPrice] = useState("asc"); // Track the sort price input
  
    const handleAccIdChange = (event) => {
      setAccId(event.target.value);
    };
  
    const handlePriceChange = (event) => {
      setPrice(event.target.value);
    };
  
    const handleSortPriceChange = (event) => {
      setSortPrice(event.target.value);
    };
  
    return (
      <div className="col-12 col-lg-3 search-zone">
        <section id="search-form" className="search-frm p-4 pb-5">
          <p className="text-center ms-text h5 m-2">Tìm kiếm</p>
          <p className="text-center small">Nhập thông tin muốn tìm</p>
          <form method="get" action="https://shoptethan.com/acc/cate/mua-kenh-tiktok-uy-tin-gia-re-an-toan-tu-dong">
            <input type="hidden" name="_token" value="TehpiWRyJ5Idp5fwske5HU7q0OMo6eA40QbkBWiz" />
            <div className="row">
              <div className="col-6 mt-3">
                <label className="form-label">Giá</label>
                <select className="form-control" name="price" value={price} onChange={handlePriceChange}>
                  <option value="">Chọn giá</option>
                  <option value="1|10000">10k trở xuống</option>
                  <option value="10000|50000">10K - 50K</option>
                  <option value="50000|100000">50K - 100K</option>
                  <option value="100000|200000">100K - 200K</option>
                  <option value="200000|300000">200K - 300K</option>
                  <option value="300000|400000">300K - 400K</option>
                  <option value="400000|500000">400K - 500K</option>
                  <option value="500000|800000">500K - 800K</option>
                  <option value="800000|1000000">800K - 1tr</option>
                  <option value="1000000|5000000">1tr - 5tr</option>
                  <option value="5000000|999999999">Trên 5tr</option>
                </select>
              </div>
              <div className="col-6 mt-3">
                <label className="form-label">Sắp xếp giá</label>
                <select className="form-control" name="sort_price" value={sortPrice} onChange={handleSortPriceChange}>
                  <option value="asc">Tăng dần</option>
                  <option value="desc">Giảm dần</option>
                </select>
              </div>
            </div>
            <div className="row">
              <div className="col-6 mt-3" id="sr_customInfo_shorts_60_0">
                <input
                  className="form-control"
                  name="info_short_0"
                  type="text"
                  value=""
                  placeholder="Chọn Máy Chủ"
                />
              </div>
            </div>
            <div className="col-12 mt-3">
              <label htmlFor="inpSearchHero" className="form-label">ID acc</label>
              <input
                className="form-control"
                name="acc_id"
                type="number"
                value={accId}
                onChange={handleAccIdChange} // Add the onChange handler here
                placeholder="Sẽ chuyển thẳng đến acc đó"
              />
            </div>
  
            <div className="col-12 mt-3">
              <button
                name="search"
                value="search"
                type="submit"
                className="offset-2 col-8 form-control btn btn-warning text-white font-weight-bold"
              >
                <i className="fab fa-searchengin ml-2"></i> Tìm kiếm
              </button>
            </div>
          </form>
        </section>
      </div>
    );
  };

const Table = () => {
    const { id } = useParams();
    console.log(id);

    const product = {
      id: 46915,
      imgSrc: "https://shoptethan.com/files/96/images/2025-01-11/58-JF.webp",
      price: "799,000",
      details: {
        follow: "XayDa",
        topic: "7Sao",
        origin: "Ảo",
        description: "xD FULL 7Sao HP - SIÊU VÍP MUA LÀ MÚC"
      },
      link: "https://shoptethan.com/acc/46915"
    };
  
    return (
      <article className="col-md-6 col-lg-4 col-6 p-0">
        <div className="genshin-product">
          <div className="wrapper product-wrapper">
            <a href={product.link}>
              <div className="image-container">
                <img style={{ borderRadius: "0.3rem" }} src={product.imgSrc} className="xc" alt={`Chủ đề : ${product.details.topic} - ${product.details.description}`} />
              </div>
            </a>
            <div className="price_cate">
              <div className="row">
                <div className="col-6">ID: {product.id}</div>
                <div className="col-6">
                  <span className="text_price_cate">{product.price}<sup>đ</sup></span>
                </div>
              </div>
            </div>
            <a href={product.link} style={{ color: "unset" }}>
              <div className="row g-0 info-line">
                <section className="col text-center" id="customInfo_shorts_60_0">
                  <label>Hành Tinh</label> {product.details.follow}
                </section>
                <section className="col text-center" id="customInfo_shorts_60_1">
                  <label>Máy Chủ</label> {product.details.topic}
                </section>
                <section className="col text-center" id="customInfo_shorts_60_2">
                  <label>Đăng Ký</label> {product.details.origin}
                </section>
              </div>
  
              <div className="hr-product"></div>
              <div className="row g-0 info-line">
                <section className="row g-0 text-center">
                  <span className="more-detail">{product.details.description}</span>
                </section>
              </div>
            </a>
          </div>
        </div>
      </article>
    );
  };

const AccountCategory = () => {
  return (
    <>
      <Head />
      <div className="hold-transition sidebar-collapse layout-top-nav">
        <div className="wrapper">
          <Navbar />

          <section className="content">
            <div className="container-fluid">
            {/* eslint-disable-next-line jsx-a11y/alt-text */}
            <center><img src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/2020031919242255224.png" class="city__icon"/></center>
              <main>
                <div>
                  <div className="container-lg">
                    <div className="row">
                      <FormSearch />
                      <Table />
                    </div>
                  </div>
                </div>
              </main>
              <Footer />
            </div>
          </section>
        </div>
      </div>
    </>
  );
};

export default AccountCategory;
